export type UiNode = { type: string; label: string; x: number; y: number; w: number; h: number; visible: boolean };
const ent = (s: string) => s.replace(/&#10;/g, '\n').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

/** Все узлы дерева доступности (iOS — весь ScrollView, в т.ч. за экраном; Android — только видимые). */
export async function nodes(): Promise<UiNode[]> {
  const src = await driver.getPageSource();
  const out: UiNode[] = [];
  const tagRe = /<([\w.]+)\s([^>]*?)\/?>/g;
  let m: RegExpExecArray | null;
  while ((m = tagRe.exec(src))) {
    const a: Record<string, string> = {};
    for (const p of m[2].matchAll(/([\w:-]+)="([^"]*)"/g)) a[p[1]] = ent(p[2]);
    if (driver.isAndroid) {
      const label = a.text || a['content-desc'] || '';
      const b = (a.bounds || '').match(/\[(\d+),(\d+)\]\[(\d+),(\d+)\]/);
      if (!label || !b) continue;
      out.push({ type: m[1], label, x: +b[1], y: +b[2], w: +b[3] - +b[1], h: +b[4] - +b[2], visible: a.displayed !== 'false' });
    } else {
      const label = a.label || a.name || a.value || '';
      if (!label || !m[1].startsWith('XCUIElementType')) continue;
      out.push({ type: m[1].replace('XCUIElementType', ''), label, x: +(a.x || 0), y: +(a.y || 0), w: +(a.width || 0), h: +(a.height || 0), visible: a.visible === 'true' });
    }
  }
  return out;
}
/** Тексты (StaticText/TextView/Android TextView) без повторов, в порядке дерева. */
export async function texts(): Promise<string[]> {
  const res: string[] = [];
  for (const n of await nodes()) {
    const isText = driver.isAndroid ? /TextView|EditText/.test(n.type) : /StaticText|TextView/.test(n.type);
    if (isText && !res.includes(n.label)) res.push(n.label);
  }
  return res;
}
export const labelAttr = () => (driver.isAndroid ? 'content-desc' : 'label');
export async function labelOf(el: El) {
  const a = String((await el.getAttribute(labelAttr()).catch(() => '')) ?? '');
  return a || String((await el.getText().catch(() => '')) ?? '');
}

// ───────────────────────── текст молитвы без огласовок ─────────────────────────

/** Убрать ניקוד и טעמים (U+0591–U+05BD, U+05BF–U+05C7); макаф U+05BE и неразрывный дефис → пробел; LRM/RLM убрать. */
export function stripNikud(t: string) {
  return t.replace(/[־‑]/g, ' ').replace(/[֑-ֽֿ-ׇ]/g, '').replace(/[‎‏]/g, '').replace(/\s+/g, ' ');
}

