/** Значение счётчика «<name>: N» (главная / «המסע שלי»). */
export async function counter(name: 'ימים רצופים' | 'תפילות היום' | 'סה״כ תפילות'): Promise<number> {
  const el = driver.isAndroid
    ? await $(`android=new UiSelector().descriptionMatches("${q(name)}: [0-9]+")`)
    : await $(`-ios predicate string:label MATCHES "${q(name)}: [0-9]+"`);
  await el.waitForExist({ timeout: 20000 });
  const t = await labelOf(el as unknown as El);
  const m = t.match(/(\d+)\s*$/);
  if (!m) throw new Error(`Счётчик «${name}» не прочитан: «${t}»`);
  return Number(m[1]);
}

/** Тип самой новой записи в «תפילות אחרונות» (первая строка под заголовком блока). null — блока нет. */
export async function newestRecentPrayer(): Promise<string | null> {
  const ns = await nodes();
  const head = ns.find((n) => n.label === 'תפילות אחרונות');
  if (!head) return null;
  const row = ns.filter((n) => n.y > head.y && ['שחרית', 'מנחה', 'ערבית'].includes(n.label)).sort((a, b) => a.y - b.y)[0];
  return row ? row.label : null;
}

