/** «N מתוך M» как числа. */
export async function counterNM(): Promise<[number, number]> {
  const [n, m] = (await pageCounter()).split(' מתוך ').map(Number);
  return [n, m];
}
/** Перейти на страницу молитвы кнопками «המשך»/«קודם» (по имени кнопки, без координат). */
export async function goPage(target: number) {
  for (let i = 0; i < 200; i++) {
    const before = await pageCounter();
    const cur = Number(before.split(' ')[0]);
    if (cur === target) return;
    await (await button(cur > target ? 'קודם' : 'המשך')).click();
    await driver.waitUntil(async () => (await pageCounter()) !== before, { timeout: 15000, timeoutMsg: `счётчик «${before}» не сменился` });
  }
  throw new Error(`не дошли до страницы ${target}`);
}

/** Весь текст молитвы по страницам (как dump.py 19.10): со стр. 1 до последней. Android — с прокруткой каждой страницы. */
export async function dumpPrayer(): Promise<{ header: string; total: number; pages: string[] }> {
  await goPage(1);
  const [, total] = await counterNM();
  const pages: string[] = [];
  for (let p = 1; p <= total; p++) {
    let t = await texts();
    if (driver.isAndroid) {
      for (let i = 0; i < 8; i++) {
        await swipeUp();
        const more = (await texts()).filter((x) => !t.includes(x));
        if (!more.length) break;
        t = t.concat(more);
      }
    }
    pages.push(t.join('\n'));
    if (p < total) await goPage(p + 1);
  }
  return { header: await shownNusach(), total, pages };
}

/** Открыть молитву из каталога в нусахе n (смена внутри молитвы через «בחירת נוסח» → «החלף») и снять текст. */
export async function dumpPrayerIn(title: string, n: Nusach) {
  await openCatalogPrayer(title);
  await ensureNusach(n);
  return dumpPrayer();
}

/** Первая страница (1-based), где текст без огласовок совпал с re; 0 — нигде. */
export function firstPage(pages: string[], re: RegExp) {
  const i = pages.findIndex((p) => re.test(stripNikud(p)));
  return i + 1;
}

