/** Времена Hebcal на дату для geonameid: ключ → «H:MM» (местное время из ISO-строки). */
export async function hebcalZmanim(geonameid: number, iso: string): Promise<Record<string, string>> {
  const r = await fetch(`https://www.hebcal.com/zmanim?cfg=json&geonameid=${geonameid}&date=${iso}`);
  if (!r.ok) throw new Error(`Hebcal ${r.status}`);
  const j = (await r.json()) as { times: Record<string, string> };
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(j.times)) {
    const m = v.match(/T(\d{2}):(\d{2})/);
    if (m) out[k] = `${Number(m[1])}:${m[2]}`;
  }
  return out;
}
export const toMin = (t: string) => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };

