/** Сохранить JSON для разбора (папка .qa/screenshots/app-regress/readiness-1910). */
export function saveArtifact(name: string, data: unknown) {
  const dir = path.join(QA_DIR, 'screenshots/app-regress/readiness-1910');
  fs.mkdirSync(dir, { recursive: true });
  const f = path.join(dir, name);
  fs.writeFileSync(f, typeof data === 'string' ? data : JSON.stringify(data, null, 1));
  return f;
}
export async function saveShot(name: string) {
  const dir = path.join(QA_DIR, 'screenshots/app-regress/readiness-1910');
  fs.mkdirSync(dir, { recursive: true });
  const f = path.join(dir, name);
  await driver.saveScreenshot(f);
  return f;
}
/** Сообщение человеку у телефона и ожидание условия до 15 минут. */
export async function waitHuman(msg: string, cond: () => Promise<boolean>, timeout = MANUAL_WAIT) {
  console.log(`[readiness-1910] ЧЕЛОВЕК: ${msg}`);
  await driver.waitUntil(cond, { timeout, interval: 3000, timeoutMsg: `ручной шаг не выполнен: ${msg}` });
}
